import { defineCatalog, type ComputedFunction } from '@json-render/core';
import { schema } from '@json-render/react/schema';
import { z } from 'zod';

const text = z.string();
const tone = z.enum(['primary', 'critical']);
const rowEvent = z.enum(['archive', 'flag', 'delete']);
const inRepeat = 'Inside a repeat, pass the item’s id as { "$template": "${id}" }, since { "$item": "id" } in params is its state path.';

const number = (value: unknown) => Number.parseFloat(String(value));
const decimals = new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 });
const plural = new Intl.PluralRules('en-US');

/** A number as text, with `unit` after it, or `units` when the number takes a plural noun: “1 cup”, “1.5 cups”. */
const counted = (n: number, unit: unknown, units: unknown) => {
  const noun = plural.select(n) === 'one' || units == null ? unit : units;
  return noun ? `${decimals.format(n)} ${String(noun)}` : decimals.format(n);
};

/**
 * Functions a spec calls with `{ "$computed": name, "args": { … } }`. SpecView hands them to json-render, the catalog
 * lists their names in the prompt and `rules` gives each one's args. Add one here and describe it in `rules`.
 */
export const functions = {
  scale: ({ amount, from, to, unit, units }) => {
    const scaled = (number(amount) * number(to)) / number(from);
    return Number.isFinite(scaled) ? counted(scaled, unit, units) : String(amount ?? '');
  },
  remaining: ({ from, take, unit, units }) => {
    const left = Math.max(0, number(from) - (number(take) || 0));
    return Number.isFinite(left) ? counted(left, unit, units) : String(from ?? '');
  },
  sum: ({ items, field, where, unless, unit, units }) => {
    const fieldOf = (item: unknown, key: unknown) => (item && typeof item === 'object' ? (item as Record<string, unknown>)[String(key)] : undefined);
    const kept = (Array.isArray(items) ? items : []).filter((item) => (where == null || !!fieldOf(item, where)) && (unless == null || !fieldOf(item, unless)));
    const total = kept.reduce<number>((t, item) => t + (number(field == null ? item : fieldOf(item, field)) || 0), 0);
    return counted(Math.max(0, total), unit, units);
  },
} satisfies Record<string, ComputedFunction>;

/**
 * The Lede components a model may use. Each prop keeps the Lede component's own name and values, so a spec reads like
 * the JSX it becomes. `catalog-fit.ts` checks that every prop here is one the component accepts.
 */
export const catalog = defineCatalog(schema, {
  components: {
    Screen: {
      props: z.object({}),
      slots: ['default'],
      description: 'The root of every spec. It stacks its children down the page with even spacing. Use it once, as the root.',
    },
    PageHeader: {
      props: z.object({ title: text, summary: text.optional(), back: z.object({ label: text }).optional() }),
      slots: ['actions'],
      events: ['back'],
      description: 'The screen’s title and its takeaway in one sentence. Use one per screen, as the first child of Screen, or of each View. Put at most two Buttons in its actions slot. In a detail View, set back to the list View’s title, such as { "label": "Inbox" }, and bind “back” to the setState that shows the list again: { "action": "setState", "params": { "statePath": "/open", "value": "" } }.',
    },
    ListGroup: {
      props: z.object({ title: text.optional(), summary: text.optional(), footer: text.optional() }),
      slots: ['default'],
      description: 'A titled list of rows. Use it for settings, messages or any set of items that people scan and pick from. Its children are ListRows. For rows from a state array, set repeat on the ListGroup and give it one ListRow child that reads each item with $item.',
    },
    ListRow: {
      props: z.object({
        title: text,
        subtitle: text.optional(),
        value: text.optional(),
        chevron: z.boolean().optional(),
        checked: z.boolean().optional(),
        actions: z.array(z.object({ label: text, tone: z.enum(['primary', 'neutral', 'critical']).optional(), event: rowEvent })).optional(),
      }),
      events: ['press', 'change', ...rowEvent.options],
      description: 'One item in a ListGroup: a title, an optional subtitle and a value on the right. The subtitle is one line that cuts off on a phone, so a reason, a problem or a difference between items goes in the title, the value, the ListGroup’s summary or a SummaryCard, never only in the subtitle. Bind “press” only to open the item’s detail View in place, with a setState of the path the Views read, such as { "action": "setState", "params": { "statePath": "/open", "value": "m1" } }: the row then shows a chevron. A row with no detail View has no press. For a setting, set checked and bind it with $bindState: the row shows a Switch named by its title and emits “change”. Each row action emits its event, such as “archive”, and shows in a menu and under a swipe.',
    },
    Button: {
      props: z.object({
        label: text,
        variant: z.enum(['filled', 'tinted', 'gray', 'plain']).optional(),
        tone: tone.optional(),
        size: z.enum(['sm', 'md', 'lg']).optional(),
        block: z.boolean().optional(),
        disabled: z.boolean().optional(),
      }),
      events: ['press'],
      description: 'An action. Use variant “filled” for the one main action on a screen and “gray” for the rest. Use tone “critical” for an action that deletes.',
    },
    TextField: {
      props: z.object({
        label: text,
        value: z.union([text, z.number()]).optional(),
        type: z.enum(['text', 'email', 'password', 'tel', 'url', 'number', 'date']).optional(),
        placeholder: text.optional(),
        hint: text.optional(),
        error: text.optional(),
        required: z.boolean().optional(),
        min: z.number().optional(),
        max: z.number().optional(),
        step: z.union([z.number().positive(), z.literal('any')]).optional(),
        pattern: z.string().optional(),
        minLength: z.number().int().min(0).optional(),
        maxLength: z.number().int().min(1).optional(),
        rows: z.number().int().min(2).max(12).optional(),
      }),
      events: ['submit'],
      description: 'A labeled text input. Bind value with $bindState. Enter in a one-line field emits “submit”: bind it to what the form’s main Button does. Word error as the fix, such as “Enter an email address with an @.” Put an example in hint, not placeholder: a placeholder in the field reads as a value already entered. For a number, set type “number” and its range with min and max; its value in state is then a number, which gt and lt compare. For a date, set type “date”: the browser draws its own picker, and its value in state is the date as YYYY-MM-DD. A number field takes any decimal unless step says otherwise, such as step 1 for whole numbers. pattern is a regular expression the whole value must match, such as "[0-9]{5}" for a 5-digit ZIP code, and minLength and maxLength bound its length. Set rows for text that runs past one line.',
    },
    Switch: {
      props: z.object({ label: text, checked: z.boolean().optional(), disabled: z.boolean().optional() }),
      events: ['change'],
      description: 'An on or off setting that applies at once, outside a list. Bind checked with $bindState. In a list, use a ListRow with checked.',
    },
    Checkbox: {
      props: z.object({ label: text, checked: z.boolean().optional(), disabled: z.boolean().optional(), required: z.boolean().optional(), error: text.optional() }),
      events: ['change'],
      description: 'A yes or no choice that applies when the form is sent. Set required when the form needs it checked, such as agreeing to terms, with an error such as “Agree to the terms to continue.” Bind checked with $bindState.',
    },
    SegmentedControl: {
      props: z.object({ label: text, options: z.array(text).min(2).max(5), value: text.optional(), required: z.boolean().optional(), error: text.optional() }),
      events: ['change'],
      description: 'A choice of two to five options, such as a view or a period. Its label shows above it. Give options that read on their own, such as “4 people” or “7:00 PM”. They sit side by side, and stack on a narrow screen. Bind value with $bindState. To make the person choose, start value at "" and set required, with an error that shows under it.',
    },
    FormSection: {
      props: z.object({ legend: text, description: text.optional() }),
      slots: ['default'],
      description: 'A group of related fields with a name, such as “Contact details”. Its children are TextFields, Switches, Checkboxes and SegmentedControls.',
    },
    EmptyState: {
      props: z.object({ title: text, description: text.optional() }),
      slots: ['action'],
      description: 'What a place is for when it has nothing in it yet, and how to fill it. Put at most one Button in its action slot.',
    },
    SummaryCard: {
      props: z.object({
        title: text,
        summary: text,
        figure: text.optional(),
        status: z.object({ tone: z.enum(['neutral', 'positive', 'caution', 'critical']), label: text }).optional(),
      }),
      description: 'One figure and the sentence that explains it, such as “3” and “invoices are overdue”. Spell the status out in its label.',
    },
    View: {
      props: z.object({}),
      slots: ['default'],
      description: 'One view of a screen that opens items in place: the list, or one item’s detail. Each View is a child of Screen and starts with its own PageHeader. One state path, such as /open, says which View shows: give the list View visible { "$state": "/open", "not": true }, so it shows while the state is still on its way, and each detail View visible { "$state": "/open", "eq": "<the item’s id>" }. Start /open at "".',
    },
  },
  actions: {
    archive: { params: z.object({ id: text }), description: `Archive an item by its id. ${inRepeat}` },
    submit: {
      params: z.object({ form: text, values: z.record(z.string(), z.unknown()).optional() }),
      description: 'Send the named form. Pass what the person entered as values, read from state: { "$state": "/signup" }. It doesn’t run while a field it reads fails its check: focus moves to that field instead.',
    },
  },
  functions,
});

export type CatalogType = keyof typeof catalog.data.components;
export type CatalogAction = keyof typeof catalog.data.actions;

/**
 * Lede's rules for a model, which `prompt` adds to json-render's. json-render's own prompt shows `repeat` on the first
 * components in a catalog, which here are Screen and PageHeader; these keep each to its one place.
 */
export const rules = [
  'Only the components under AVAILABLE COMPONENTS and the actions under AVAILABLE ACTIONS exist. Use no other type or action name.',
  'Screen is the root of every spec, and there is one. PageHeader is its first child, and there is one, unless the screen opens items in place: then each child of Screen is a View with a PageHeader of its own.',
  'To let a person open an item, write its detail in the same spec: a Screen whose children are Views, the list View and one detail View per item, each with its own PageHeader. A row’s or a Button’s press sets the path the Views read, and the detail’s PageHeader takes back with the list View’s title and binds “back” to set the path to "" again. For a list from a state array, write one detail View with repeat on the same array, visible [{ "$state": "/open" }, { "$item": "id", "eq": { "$state": "/open" } }], and set the path with { "$template": "${id}" }. A row or a Button that opens nothing in the spec has no press.',
  'To list items from a state array, put repeat on a ListGroup, with one ListRow child that reads each item with $item.',
  'Stream a list’s rows by appending them in their final order, one item at a time. Never reorder rows or insert one above another mid-stream: a person can use a row while later rows arrive, and their change stays with its position in the list.',
  'Inside a repeat, a condition in $cond or visible reads the item too, such as { "$cond": { "$item": "paid" }, "$then": "Paid", "$else": "Due" }.',
  'In action params, { "$item": "id" } is the item’s state path. To pass the value, write { "$template": "${id}" }.',
  'An event runs several actions in order when its binding is an array, such as "press": [{ "action": "setState", … }, { "action": "submit", … }].',
  'To show a value worked out from others, use $computed. { "$computed": "scale", "args": { "amount": …, "from": …, "to": …, "unit": …, "units": … } } returns amount × to ÷ from. { "$computed": "remaining", "args": { "from": …, "take": …, "unit": …, "units": … } } returns from − take, and never less than 0. { "$computed": "sum", "args": { "items": { "$state": "/bills" }, "field": "amount", "unless": "paid", "unit": …, "units": … } } adds up field across a state array, keeping only items whose where field is set and whose unless field isn’t, and never returns less than 0. Each arg can be a literal, { "$state": … }, which can read a whole array, or { "$item": … }, and a number inside text, such as “6 people”, counts as 6.',
  'Text reads right for every value it can show. Give a number its noun through unit and units, such as "unit": "cup", "units": "cups" for “1 cup” and “1.5 cups”, rather than in a $template.',
  'A field is checked when an action reads it. An action whose params read a field that is empty and required, out of its min and max, off its step, not matching its pattern, shorter than its minLength or not the email or URL its type asks for doesn’t run: the field shows its error and focus moves to it. So give each checked field an error as plain text worded as the fix, such as "error": "Enter minutes from 5 to 240.". An error names only what the field checks: to ask for a 5-digit ZIP code, set its pattern too. It shows only once a check holds an action back, and goes when the field passes. Bind the same actions to the field’s submit, so Enter in it does what its Button does. To clear a form after it sends, end the binding with a setState that empties its fields.',
  'Each spec is a whole screen, with its root, every element and the state it needs, even when it changes a screen from earlier in the conversation. An earlier screen’s state is what the person left in it, so carry over what they entered.',
  'Every control does something: it changes a setting, a value another element shows or a value an action sends, or it runs an action. A spec can’t sort or filter a list, so it has no sort or filter controls.',
];

/**
 * json-render's prompt shows its shapes with components and actions from other catalogs, such as Card, Select and
 * `loadCities`, and with Screen where this catalog would use ListGroup or Button. Each pair rewrites one of those in
 * this catalog's terms; `tests/specs.test.tsx` fails when a json-render update changes the text a pair looks for.
 */
export const promptFixes: ReadonlyArray<readonly [string, string]> = [
  ['{"type":"Card","props":{"title":"Hello"},"children":[]}', '{"type":"Screen","props":{},"children":[]}'],
  ['"type":"Screen","props":{},"repeat"', '"type":"ListGroup","props":{},"repeat"'],
  ['{"type":"PageHeader","props":{"title":{"$item":"title"}},"children":[]}', '{"type":"ListRow","props":{"title":{"$item":"title"}},"children":[]}'],
  ['{"type":"Screen","props":{},"on":{"press"', '{"type":"Button","props":{"label":"Save"},"on":{"press"'],
  ['A Screen with on: {', 'A Button with on: {'],
  ['"color": { "$cond": { "$state": "/activeTab", "eq": "home" }, "$then": "#007AFF", "$else": "#8E8E93" }', '"value": { "$cond": { "$state": "/settings/push" }, "$then": "On", "$else": "Off" }'],
  ['Example (cascading select — country changes trigger city loading):', 'Example (a new period sends the page back to its start):'],
  ['{"type":"Select","props":{"value":{"$bindState":"/form/country"},"options":["US","Canada","UK"]},"watch":{"/form/country":{"action":"loadCities","params":{"country":{"$state":"/form/country"}}}},"children":[]}',
    '{"type":"SegmentedControl","props":{"label":"Period","options":["Today","This week"],"value":{"$bindState":"/period"}},"watch":{"/period":{"action":"setState","params":{"statePath":"/page","value":1}}},"children":[]}'],
];

/** The system prompt for a model that writes Lede screens: json-render's, in this catalog's terms, with `rules`. */
export function prompt(options: { system?: string; mode?: 'inline' | 'standalone' } = {}) {
  const text = catalog.prompt({ mode: options.mode ?? 'inline', system: options.system, customRules: rules });
  return promptFixes.reduce((out, [from, to]) => out.replaceAll(from, to), text);
}

import type { JSXElementConstructor } from 'react';
import type { z } from 'zod';
import type { Button } from '../button';
import type { Checkbox } from '../checkbox';
import type { ListGroup, ListRow } from '../list';
import type { SegmentedControl } from '../segmented-control';
import type { Switch } from '../switch';
import type { TextField } from '../text-field';
import type { EmptyState } from '../blocks/empty-state';
import type { FormSection } from '../blocks/form-section';
import type { PageHeader } from '../blocks/page-header';
import type { SummaryCard } from '../blocks/summary-card';
import type { catalog } from './catalog';

// A typecheck, not a runtime test: `tsc --noEmit` fails when a catalog entry lets a model set a prop its Lede
// component doesn't take, or a value the component's type doesn't allow. The error names the entry and the prop.

type Entries = typeof catalog.data.components;
type Name = keyof Entries;
type Props<K extends Name> = z.infer<Entries[K]['props']>;

/** The Lede component behind each entry. Screen and View are this page's own stacking `<div>`s, so they have none. */
interface Lede {
  Screen: null;
  View: null;
  PageHeader: typeof PageHeader;
  ListGroup: typeof ListGroup;
  ListRow: typeof ListRow;
  Button: typeof Button;
  TextField: typeof TextField;
  Switch: typeof Switch;
  Checkbox: typeof Checkbox;
  SegmentedControl: typeof SegmentedControl;
  FormSection: typeof FormSection;
  EmptyState: typeof EmptyState;
  SummaryCard: typeof SummaryCard;
}

/**
 * Props the registry reads and turns into something else, such as a Button's `label`, which becomes its children, or a
 * SegmentedControl's `error`, which it draws under the control, or a PageHeader's `back`, a label with no `href`, which
 * it gives an `onClick` that shows the list View again.
 */
interface Adapted {
  PageHeader: 'back';
  ListRow: 'checked';
  Button: 'label';
  Checkbox: 'label' | 'error';
  SegmentedControl: 'error';
}

// TextField's props are a union (an input or a textarea), so a prop counts when any member takes it.
type Accepted<K extends Name> = Lede[K] extends JSXElementConstructor<infer P> ? P : Record<never, never>;
type KeysOf<T> = T extends unknown ? keyof T : never;
type ValueOf<T, P> = T extends unknown ? (P extends keyof T ? T[P] : never) : never;
type Own<K extends Name> = Exclude<keyof Props<K>, K extends keyof Adapted ? Adapted[K] : never>;
type Unknown<K extends Name> = Exclude<Own<K>, KeysOf<Accepted<K>>>;
type Mistyped<K extends Name> = {
  [P in Own<K> & KeysOf<Accepted<K>>]: Props<K>[P] extends ValueOf<Accepted<K>, P> ? never : P;
}[Own<K> & KeysOf<Accepted<K>>];
type Fit<K extends Name> = Lede[K] extends null ? true : [Unknown<K>, Mistyped<K>] extends [never, never]
  ? true
  : { unknownProps: Unknown<K>; mistypedProps: Mistyped<K> };

export const fit: { [K in Name]: Fit<K> } = {
  Screen: true,
  View: true,
  PageHeader: true,
  ListGroup: true,
  ListRow: true,
  Button: true,
  TextField: true,
  Switch: true,
  Checkbox: true,
  SegmentedControl: true,
  FormSection: true,
  EmptyState: true,
  SummaryCard: true,
};

import * as React from 'react';
import { defineRegistry, useActions, useBoundProp, useRepeatScope, useStateStore, type ComponentRegistry } from '@json-render/react';
import { resolveActionParam, type ActionBinding, type Spec } from '@json-render/core';
import { Button } from '../button';
import { Checkbox } from '../checkbox';
import { ListGroup, ListRow } from '../list';
import { SegmentedControl } from '../segmented-control';
import { Switch } from '../switch';
import { TextField } from '../text-field';
import { EmptyState } from '../blocks/empty-state';
import { FormSection } from '../blocks/form-section';
import { PageHeader } from '../blocks/page-header';
import { focusLanding } from '../input-modality';
import { SummaryCard } from '../blocks/summary-card';
import { catalog, functions } from './catalog';
import { opensView } from './check';

/**
 * The level of a spec's title. A spec renders below its host page's own h1, so it starts at h2 by default, and a host
 * that puts it under another heading, such as a chat message's author, provides level 3. Sections sit one below.
 */
export const SpecHeadingLevel = React.createContext<2 | 3>(2);
const useLevels = () => {
  const title = React.useContext(SpecHeadingLevel);
  return { title, section: (title + 1) as 3 | 4 };
};

/** The element around a SpecView's screen, where a press looks for the fields its actions read. */
export const SpecRoot = React.createContext<React.RefObject<HTMLElement | null> | null>(null);
/** The spec a SpecView draws, which a row reads to know whether the View its press shows has arrived. */
export const SpecShown = React.createContext<Spec | null>(null);
/** The `on` bindings of the element being drawn, which defineRegistry's render props leave out. */
const ElementOn = React.createContext<Record<string, ActionBinding | ActionBinding[]> | undefined>(undefined);
/** The drawn element's key in the spec, with its item's index inside a repeat: a name that outlives a remount. */
const ElementId = React.createContext('');

interface Drill {
  /** The element whose press came last, by `ElementId`. A detail View's PageHeader takes it as the control that opened it. */
  pressed: React.RefObject<string | null>;
  /** The control that opened a detail on its way out, which takes focus as it draws again. */
  returnTo: React.RefObject<string | null>;
  /** Focus is inside this screen, so its Escape belongs to the open detail. */
  within: boolean;
}
const DrillContext = React.createContext<Drill | null>(null);
/**
 * Each element's key in the spec a SpecView draws. json-render hands a component a copy of its element with the props
 * resolved, and the copy keeps the element's own `children` and `on`, so those find the key.
 */
export const SpecKeys = React.createContext<ReadonlyMap<unknown, string>>(new Map());
export const specKeys = (spec: Spec | null): ReadonlyMap<unknown, string> =>
  new Map(Object.entries(spec?.elements ?? {}).flatMap(([key, el]) => [el.children, el.on].filter(Boolean).map((part) => [part, key] as const)));

/**
 * Opening an item in place: a press notes the control that made it, the detail's title takes focus when it shows, and
 * Back returns focus to that control. SpecView puts it around each screen. Escape backs out of a detail only while
 * focus is inside its screen, so it never reaches the page around it or another screen.
 */
export function DrillScope({ children }: { children: React.ReactNode }) {
  const root = React.useContext(SpecRoot);
  const pressed = React.useRef<string | null>(null);
  const returnTo = React.useRef<string | null>(null);
  const [within, setWithin] = React.useState(false);
  React.useEffect(() => {
    const el = root?.current;
    if (!el) return;
    const update = () => setWithin(el.contains(document.activeElement));
    el.addEventListener('focusin', update);
    el.addEventListener('focusout', update);
    document.addEventListener('focusin', update);
    return () => {
      el.removeEventListener('focusin', update);
      el.removeEventListener('focusout', update);
      document.removeEventListener('focusin', update);
    };
  }, [root]);
  const drill = React.useMemo(() => ({ pressed, returnTo, within }), [within]);
  return <DrillContext.Provider value={drill}>{children}</DrillContext.Provider>;
}

/**
 * The control a press came from, for the detail it opens to hand focus back to. When Back takes the detail away, the
 * control takes focus in the commit that draws it again, before a frame can show focus on `<body>`.
 */
function usePress() {
  const drill = React.useContext(DrillContext);
  const root = React.useContext(SpecRoot);
  const id = React.useContext(ElementId);
  React.useLayoutEffect(() => {
    if (!drill || drill.returnTo.current !== id) return;
    drill.returnTo.current = null;
    focusLanding(root?.current && controlFor(root.current, id));
  }, []);
  return { id, note: () => { if (drill) drill.pressed.current = id; } };
}
const controlFor = (scope: ParentNode, id: string) =>
  scope.querySelector<HTMLElement>(`[data-row-id="${CSS.escape(id)}"] .ld-row-target, [data-jr-id="${CSS.escape(id)}"]`);

/**
 * A detail View's header: Lede's PageHeader with a back button. When it shows because a press took the list away, its
 * title takes focus. Its back button, or Escape while focus is in the screen, emits “back”, and once the list is back
 * focus returns to the control that opened the detail, or to the screen's title when that control is gone.
 */
function DetailHeader({ title, summary, back, actions, level, onBack }: {
  title: string; summary?: string; back: { label: string }; actions?: React.ReactNode; level: 2 | 3; onBack: () => void;
}) {
  const drill = React.useContext(DrillContext);
  const root = React.useContext(SpecRoot);
  const heading = React.useRef<HTMLHeadingElement>(null);
  const [openedBy] = React.useState(() => drill?.pressed.current ?? null);
  const leaving = React.useRef(false);
  const goBack = () => {
    leaving.current = true;
    if (drill) drill.returnTo.current = openedBy;
    onBack();
  };
  React.useLayoutEffect(() => {
    const scope = root?.current;
    const active = document.activeElement;
    if (!openedBy || !scope || (active && active !== document.body) || controlFor(scope, openedBy)) return;
    focusLanding(heading.current);
  }, []);
  // When the control that opened the detail is gone, such as a row archived from it, the list's title takes focus.
  React.useLayoutEffect(() => () => {
    if (!leaving.current) return;
    queueMicrotask(() => {
      const scope = root?.current;
      if (drill) drill.returnTo.current = null;
      const active = document.activeElement;
      if (!scope || (active && active !== document.body && active.isConnected)) return;
      focusLanding(scope.querySelector<HTMLElement>('.ld-page-title'));
    });
  }, []);
  return (
    <PageHeader
      title={title}
      summary={summary}
      actions={actions}
      headingLevel={level}
      headingRef={heading}
      focusOnMount={false}
      back={{ label: back.label, onSelect: goBack }}
      backOnEscape={!!drill?.within}
    />
  );
}

/** Every `$state` path a binding's params read, such as `/form` in `{ "values": { "$state": "/form" } }`. */
function statePaths(value: unknown): string[] {
  if (!value || typeof value !== 'object') return [];
  if (!Array.isArray(value) && typeof (value as { $state?: unknown }).$state === 'string') return [(value as { $state: string }).$state];
  return Object.values(value).flatMap(statePaths);
}

type Field = HTMLInputElement | HTMLTextAreaElement;
interface Checks {
  /** Each field whose check held back an action, by name, with the browser's message for what it needs. */
  shown: ReadonlyMap<string, string>;
  show: (fields: Field[]) => void;
  /** Each field's own `error` from the spec, by name, which it shows in place of the browser's message. */
  errors: Map<string, string>;
  /** Called when a field's value changes: a field that now passes drops its error, and one that still fails keeps it. */
  recheck: (name: string, valid: boolean, message: string) => void;
}
const Checked = React.createContext<Checks | null>(null);

/** An action held back by fields it reads: the action, and each failing field's name and the error it shows. */
export interface HeldAction {
  action: string;
  fields: Array<{ name: string; message: string }>;
}
/** Where SpecView's `onActionHeld` reaches `useCheckedEmit`. */
export const ActionHeld = React.createContext<((held: HeldAction) => void) | undefined>(undefined);

/** Holds which fields show their error. SpecView puts it around each screen. */
export function FieldChecks({ children }: { children: React.ReactNode }) {
  const [shown, setShown] = React.useState<ReadonlyMap<string, string>>(new Map());
  const [errors] = React.useState(() => new Map<string, string>());
  const checks = React.useMemo<Checks>(() => ({
    shown,
    errors,
    show: (fields) => setShown((prev) => new Map([...prev, ...fields.map((f) => [f.name, f.validationMessage] as const)])),
    recheck: (name, valid, message) => setShown((prev) => {
      if (!prev.has(name) || (!valid && prev.get(name) === message)) return prev;
      const next = new Map(prev);
      if (valid) next.delete(name);
      else next.set(name, message);
      return next;
    }),
  }), [shown, errors]);
  return <Checked.Provider value={checks}>{children}</Checked.Provider>;
}

/**
 * A field's error, shown once its check holds back an action: the spec's `error`, or the browser's message without
 * one. Each change to its value checks it again, whether the person typed it or an action or the stream set it.
 */
function useFieldError(name: string | undefined, error: string | undefined, value: unknown) {
  const checks = React.useContext(Checked);
  const root = React.useContext(SpecRoot);
  const message = name === undefined ? undefined : checks?.shown.get(name);
  const shown = message !== undefined;
  React.useEffect(() => {
    if (name === undefined || !checks) return;
    if (!error) return;
    checks.errors.set(name, error);
    return () => { checks.errors.delete(name); };
  }, [name, error, checks]);
  React.useEffect(() => {
    if (!shown || name === undefined) return;
    const field = (root?.current ?? document).querySelector<Field>(`[name="${CSS.escape(name)}"]`);
    if (field) checks?.recheck(name, field.validity.valid, field.validationMessage);
  }, [value, shown, name, root, checks]);
  return message === undefined ? undefined : error || message;
}

/**
 * An event's emit, which runs its actions in order as json-render's does, each with its params resolved against the
 * state as it is then and the repeat item the element is drawn for. Right before each action, the fields its params
 * read are checked: one that is empty and required, outside its min and max, or not the email or URL its type asks for
 * holds that action and the rest back. Each field it reads that fails shows its error, and focus moves to the first.
 * Each field's `name` is the state path it binds. Every event of every element runs through here.
 */
function useCheckedEmit(on: Record<string, ActionBinding | ActionBinding[]> | undefined) {
  const root = React.useContext(SpecRoot);
  const checks = React.useContext(Checked);
  const report = React.useContext(ActionHeld);
  const { execute } = useActions();
  const { getSnapshot } = useStateStore();
  const repeat = useRepeatScope();
  return async (event: string) => {
    const bound = on?.[event];
    for (const b of bound ? (Array.isArray(bound) ? bound : [bound]) : []) {
      const scope: ParentNode = root?.current ?? document;
      const held = [...scope.querySelectorAll<Field>('input[name]:invalid, textarea[name]:invalid')]
        .filter((f) => statePaths(b.params).some((p) => f.name === p || f.name.startsWith(`${p}/`)));
      if (held.length) {
        checks?.show(held);
        report?.({ action: b.action, fields: held.map((f) => ({ name: f.name, message: checks?.errors.get(f.name) || f.validationMessage })) });
        held[0].focus();
        return;
      }
      const ctx = { stateModel: getSnapshot(), repeatItem: repeat?.item, repeatIndex: repeat?.index, repeatBasePath: repeat?.basePath, functions };
      await execute(b.params ? { ...b, params: Object.fromEntries(Object.entries(b.params).map(([k, v]) => [k, resolveActionParam(v, ctx)])) } : b);
    }
  };
}

/**
 * Each catalog type drawn by its Lede component. The spec's PageHeader leaves focus where the reader is, and its title
 * takes the level SpecView gives it.
 */
const drawn = defineRegistry(catalog, {
  components: {
    Screen: ({ children }) => <div className="ld-flow ld-flow-stack">{children}</div>,
    View: ({ children }) => <div className="ld-flow-stack">{children}</div>,
    PageHeader: ({ props, slots, emit }) => {
      const { title } = useLevels();
      if (props.back) return <DetailHeader title={props.title} summary={props.summary} back={props.back} actions={slots?.actions} level={title} onBack={() => emit('back')} />;
      return <PageHeader title={props.title} summary={props.summary} actions={slots?.actions} headingLevel={title} focusOnMount={false} />;
    },
    ListGroup: ({ props, children }) => (
      <ListGroup title={props.title} summary={props.summary} footer={props.footer} headingLevel={useLevels().section}>{children}</ListGroup>
    ),
    ListRow: ({ props, bindings, emit, on }) => {
      const [checked, setChecked] = useBoundProp(props.checked, bindings?.checked);
      const spec = React.useContext(SpecShown);
      const raw = React.useContext(ElementOn)?.press;
      // A row's press opens its detail View, so the row acts once that View has arrived, and not while it streams.
      const opens = on('press').bound && (spec ? opensView(spec, raw) : true);
      const { id, note } = usePress();
      return (
        <ListRow
          rowKey={id}
          title={props.title}
          subtitle={props.subtitle}
          value={props.value}
          // A chevron says the row leads somewhere, so it shows only on a row whose press opens a View.
          chevron={opens && props.chevron !== false}
          onClick={opens ? () => { note(); emit('press'); } : undefined}
          trailing={checked === undefined ? undefined : (
            <Switch aria-label={props.title} checked={checked} onCheckedChange={(next) => { setChecked(next); emit('change'); }} />
          )}
          actions={props.actions?.map((a) => ({ label: a.label, tone: a.tone, onSelect: () => emit(a.event) }))}
        />
      );
    },
    Button: ({ props, emit }) => {
      const { id, note } = usePress();
      return (
        <Button data-jr-id={id} variant={props.variant} tone={props.tone} size={props.size} block={props.block} disabled={props.disabled} onClick={() => { note(); emit('press'); }}>
          {props.label}
        </Button>
      );
    },
    TextField: ({ props, bindings, on, emit }) => {
      const [value, setValue] = useBoundProp(props.value, bindings?.value);
      const submit = on('submit');
      const error = useFieldError(bindings?.value, props.error, value);
      return (
        <TextField
          label={props.label}
          type={props.type}
          placeholder={props.placeholder}
          hint={props.hint}
          error={error}
          required={props.required}
          min={props.min}
          max={props.max}
          // Without a step a number field allows whole steps only, so 7.5 would fail; a spec asks for whole numbers with step 1.
          step={props.type === 'number' ? (props.step ?? 'any') : undefined}
          pattern={props.pattern}
          minLength={props.minLength}
          maxLength={props.maxLength}
          name={bindings?.value}
          rows={props.rows}
          value={value ?? ''}
          // A number field keeps a number in state, so a condition's gt and lt compare it.
          onChange={(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
            const input = e.currentTarget;
            setValue(props.type === 'number' && input.value !== '' ? (input as HTMLInputElement).valueAsNumber : input.value);
          }}
          onKeyDown={submit.bound && !props.rows ? (e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => {
            if (e.key === 'Enter' && !e.nativeEvent.isComposing) { e.preventDefault(); emit('submit'); }
          } : undefined}
        />
      );
    },
    Switch: ({ props, bindings, emit }) => {
      const [checked, setChecked] = useBoundProp(props.checked, bindings?.checked);
      return <Switch label={props.label} disabled={props.disabled} checked={!!checked} onCheckedChange={(next) => { setChecked(next); emit('change'); }} />;
    },
    Checkbox: ({ props, bindings, emit }) => {
      const [checked, setChecked] = useBoundProp(props.checked, bindings?.checked);
      const error = useFieldError(bindings?.checked, props.error, checked);
      const errorId = React.useId();
      return (
        <div className="ld-field" data-invalid={error ? '' : undefined}>
          {/* Lede's Checkbox is the box alone. Its label sits in a column of its own, so a long one wraps beside the box. */}
          <label className="ld-checkbox-field">
            <Checkbox
              checked={!!checked}
              disabled={props.disabled}
              required={props.required}
              name={bindings?.checked}
              aria-describedby={error ? errorId : undefined}
              aria-invalid={error ? true : undefined}
              onChange={(e) => { setChecked(e.currentTarget.checked); emit('change'); }}
            />
            <span className="ld-checkbox-label">{props.label}</span>
          </label>
          {error ? <p id={errorId} className="ld-field-hint">{error}</p> : null}
        </div>
      );
    },
    SegmentedControl: ({ props, bindings, emit }) => {
      const [value, setValue] = useBoundProp(props.value, bindings?.value);
      const errorId = React.useId();
      const error = useFieldError(bindings?.value, props.error, value);
      // Lede's SegmentedControl names its group with a hidden legend, for a screen where a heading beside it says what
      // it picks. A model's screen may have none, so the label shows here too, hidden from assistive tech, which
      // reads the legend. An error shows under it, as a TextField's does.
      return (
        <div className="ld-field" data-invalid={error ? '' : undefined}>
          <p className="ld-field-label" aria-hidden="true">{props.label}</p>
          <SegmentedControl
            label={props.label}
            options={props.options}
            value={value}
            name={bindings?.value}
            required={props.required}
            aria-describedby={error ? errorId : undefined}
            aria-invalid={!!error}
            onValueChange={(next) => { setValue(next); emit('change'); }}
          />
          {error ? <p id={errorId} className="ld-field-hint">{error}</p> : null}
        </div>
      );
    },
    FormSection: ({ props, children }) => <FormSection legend={props.legend} description={props.description}>{children}</FormSection>,
    EmptyState: ({ props, slots }) => (
      <EmptyState title={props.title} description={props.description} action={slots?.action} headingLevel={useLevels().section} />
    ),
    SummaryCard: ({ props }) => (
      <SummaryCard title={props.title} summary={props.summary} figure={props.figure} status={props.status} headingLevel={useLevels().section} />
    ),
  },
  // defineRegistry asks for the catalog's actions. SpecView runs the host's `handlers` in their place.
  actions: { archive: async () => undefined, submit: async () => undefined },
});

/**
 * The registry, each entry given its element's `on` bindings and its `ElementId`, with `emit` and `on` running every
 * event through `useCheckedEmit`.
 */
export const registry: ComponentRegistry = Object.fromEntries(
  Object.entries(drawn.registry).map(([type, Draw]) => [
    type,
    function Drawn(ctx: React.ComponentProps<typeof Draw>) {
      const keys = React.useContext(SpecKeys);
      const key = keys.get(ctx.element.children) ?? keys.get(ctx.element.on) ?? type;
      const index = useRepeatScope()?.index;
      const checked = useCheckedEmit(ctx.element.on);
      const emit = (event: string) => { void checked(event); };
      const on = (event: string) => ({ ...ctx.on(event), emit: () => emit(event) });
      return (
        <ElementId.Provider value={index === undefined ? key : `${key}/${index}`}>
          <ElementOn.Provider value={ctx.element.on}><Draw {...ctx} emit={emit} on={on} /></ElementOn.Provider>
        </ElementId.Provider>
      );
    },
  ]),
);

import * as React from 'react';
import { createStateStore, type InferActionParams, type Spec, type StateStore } from '@json-render/core';
import { JSONUIProvider, Renderer, type ComponentRenderer } from '@json-render/react';
import { focusLanding } from '../input-modality';
import { catalog, functions, type CatalogAction } from './catalog';
import { ActionHeld, DrillScope, FieldChecks, registry, SpecHeadingLevel, SpecKeys, specKeys, SpecRoot, SpecShown, type HeldAction } from './registry';

export type { HeldAction } from './registry';

/**
 * The catalog's actions, each called with its params, typed from its schema, when a spec runs it. Add an action to the
 * catalog and it's here.
 */
export type SpecHandlers = { [K in CatalogAction]?: (params: InferActionParams<typeof catalog, K>) => void | Promise<void> };
type State = Record<string, unknown>;

export interface SpecViewProps {
  /** The spec so far, such as `specFromParts(message.parts)` while a reply streams. */
  spec: Spec | null;
  /** True while the spec streams: elements still on their way draw nothing until they arrive. */
  streaming?: boolean;
  /** The level of the spec's title. Default 2, under a page's h1; a chat message's author heading makes it 3. */
  headingLevel?: 2 | 3;
  /**
   * Called when the spec runs a catalog action. Read through a ref, so each call reaches the latest, and an inline
   * object is fine. One that returns a promise holds the actions after it until it settles. An action whose params read a field that fails its check doesn't run, so its handler isn't called.
   */
  handlers?: SpecHandlers;
  /**
   * Drawn for an element whose type the registry doesn't have, such as one from a newer catalog. Without it, that
   * element draws nothing and json-render logs a warning.
   */
  fallback?: ComponentRenderer;
  /** Called with the screen's whole state after each change, such as for a chat to send what the person entered. */
  onStateChange?: (state: State) => void;
  /**
   * Called when an action doesn't run because fields it reads fail their checks, with the action and each field's name
   * and the error it shows. Read through a ref, so an inline function is fine.
   */
  onActionHeld?: (held: HeldAction) => void;
}

/**
 * The screen a spec describes, drawn with Lede. It draws once the spec's root element arrives, and state that arrives
 * after it, as a model streams it, fills in what's drawn: a list drawn with repeat gains a row per item. The person can
 * use the screen while the rest streams in.
 */
export function SpecView({ spec, ...props }: SpecViewProps) {
  return spec?.elements[spec.root] ? <Screen spec={spec} {...props} /> : null;
}

const actionNames = Object.keys(catalog.data.actions) as CatalogAction[];

function Screen({ spec, streaming = false, headingLevel = 2, handlers, fallback, onStateChange, onActionHeld }: SpecViewProps & { spec: Spec }) {
  const root = React.useRef<HTMLDivElement>(null);
  const [{ store, sync }] = React.useState(() => specStore(spec.state));
  React.useLayoutEffect(() => sync(spec.state), [spec.state, sync]);
  React.useEffect(() => {
    if (!onStateChange) return;
    onStateChange(store.getSnapshot());
    return store.subscribe(() => onStateChange(store.getSnapshot()));
  }, [store, onStateChange]);
  const held = React.useRef(onActionHeld);
  React.useLayoutEffect(() => { held.current = onActionHeld; });
  const [report] = React.useState(() => (h: HeldAction) => held.current?.(h));
  // json-render keeps the handlers it mounts with, so it gets these, which call the latest.
  const latest = React.useRef(handlers);
  React.useLayoutEffect(() => { latest.current = handlers; });
  const [dispatch] = React.useState(() => Object.fromEntries(actionNames.map((name) => [name, (params: Record<string, unknown>) =>
    (latest.current?.[name] as ((p: Record<string, unknown>) => void | Promise<void>) | undefined)?.(params)])));
  useKeptFocus(root);
  useTokensCheck(root);
  const keys = React.useMemo(() => specKeys(spec), [spec]);
  return (
    <SpecHeadingLevel.Provider value={headingLevel}>
      <SpecRoot.Provider value={root}>
        <div ref={root}>
          <JSONUIProvider registry={registry} functions={functions} store={store} handlers={dispatch}>
            <FieldChecks>
              <ActionHeld.Provider value={report}>
                <SpecShown.Provider value={spec}>
                  <SpecKeys.Provider value={keys}>
                    <DrillScope>
                      <Renderer spec={spec} registry={registry} loading={streaming} fallback={fallback} />
                    </DrillScope>
                  </SpecKeys.Provider>
                </SpecShown.Provider>
              </ActionHeld.Provider>
            </FieldChecks>
          </JSONUIProvider>
        </div>
      </SpecRoot.Provider>
    </SpecHeadingLevel.Provider>
  );
}

/** Each value in a state object by its JSON Pointer. Objects open up; arrays, empty objects and the rest are values. */
function leaves(state: State, prefix = ''): Array<[string, unknown]> {
  return Object.entries(state).flatMap(([key, value]) => {
    const path = `${prefix}/${key.replaceAll('~', '~0').replaceAll('/', '~1')}`;
    const open = value !== null && typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length > 0;
    return open ? leaves(value as State, path) : [[path, value] as [string, unknown]];
  });
}
const same = (a: unknown, b: unknown) => a === b || JSON.stringify(a) === JSON.stringify(b);

/**
 * The screen's state. A spec's state arrives as it streams; each value the person changes, by typing, a press or an
 * action, keeps their change, and the stream no longer writes it or anything under it. A value the stream writes above
 * one of theirs, such as a list that gains a row after they switched on an earlier one, still arrives, with their
 * change written back on top. `sync` takes the spec's state so far.
 */
export function specStore(initial: State = {}): { store: StateStore; sync: (state?: State) => void } {
  const inner = createStateStore(initial);
  const touched = new Set<string>();
  let sent = new Map(leaves(initial));
  const theirs = (path: string) => [...touched].some((t) => path === t || path.startsWith(`${t}/`));
  const under = (path: string) => [...touched].filter((t) => t.startsWith(`${path}/`));
  const store: StateStore = {
    ...inner,
    set: (path, value) => { touched.add(path); inner.set(path, value); },
    update: (updates) => { for (const path of Object.keys(updates)) touched.add(path); inner.update(updates); },
  };
  const sync = (state: State = {}) => {
    const next = new Map(leaves(state));
    const changed = [...next].filter(([path, value]) => !same(sent.get(path), value) && !theirs(path));
    sent = next;
    const kept = changed.flatMap(([path]) => under(path)).map((t) => [t, inner.get(t)] as const);
    if (changed.length) inner.update(Object.fromEntries([...changed, ...kept]));
  };
  return { store, sync };
}

const FOCUSABLE = 'button:not(:disabled), a[href], input:not(:disabled), textarea:not(:disabled), select:not(:disabled), [tabindex]:not([tabindex="-1"])';
/** The first control in a node that a person can reach: shown, and not in an inert or hidden part, such as a row's swipe actions. */
const focusable = (node: Node | null) =>
  node instanceof HTMLElement
    ? [node, ...node.querySelectorAll<HTMLElement>(FOCUSABLE)].find((el) => el.matches(FOCUSABLE) && !el.closest('[inert], [aria-hidden="true"]') && el.checkVisibility({ visibilityProperty: true })) ?? null
    : null;
const along = (node: Node | null, step: 'nextSibling' | 'previousSibling') => {
  for (let at = node; at; at = at[step]) {
    const found = focusable(at);
    if (found) return found;
  }
  return null;
};

/**
 * Where focus goes when the control that held it leaves: the control that took its place, a neighbor, the title, or
 * the screen itself when it shows none of those.
 */
function landing(records: MutationRecord[], gone: Element, root: HTMLElement): HTMLElement {
  const added = records.flatMap((r) => [...r.addedNodes]).filter((n) => root.contains(n)).map(focusable).find(Boolean);
  if (added) return added;
  const removal = records.find((r) => [...r.removedNodes].some((n) => n === gone || n.contains(gone)));
  const neighbor = removal && (along(removal.nextSibling, 'nextSibling') ?? along(removal.previousSibling, 'previousSibling'));
  if (neighbor && root.contains(neighbor)) return neighbor;
  const title = root.querySelector<HTMLElement>('.ld-page-title');
  if (title) return title;
  root.tabIndex = -1;
  return root;
}

/**
 * A press can take away the control that made it: a row action that hides its row, or a button that hides itself and
 * shows another. Focus then moves to the control that took its place, the next or previous control beside it, the
 * screen's title or the screen, so it never falls to `<body>`. A control in a menu or other popup counts as the one that opened it.
 */
function useKeptFocus(root: React.RefObject<HTMLElement | null>) {
  React.useEffect(() => {
    const screen = root.current;
    if (!screen) return;
    let last: Element | null = null;
    let away: Element | null = null;
    let next: HTMLElement | null = null;
    const onFocus = (event: FocusEvent) => {
      const target = event.target as Element;
      if (screen.contains(target)) [last, away] = [target, null];
      else away = target;
      next = null;
    };
    const observer = new MutationObserver((records) => {
      if (!last || last.isConnected) return;
      next ??= landing(records, last, screen);
      if (away?.isConnected) return;
      const lost = !document.activeElement || document.activeElement === document.body;
      if (lost && next?.isConnected) focusLanding(next);
    });
    observer.observe(document.body, { childList: true, subtree: true });
    document.addEventListener('focusin', onFocus);
    return () => {
      observer.disconnect();
      document.removeEventListener('focusin', onFocus);
    };
  }, [root]);
}

// Bundlers replace `process.env.NODE_ENV` in the browser; where nothing does, there is no `process` and no warning.
declare const process: { env: Record<string, string | undefined> };
const development = (() => {
  try {
    return process.env.NODE_ENV !== 'production';
  } catch {
    return false;
  }
})();
let warned = false;
/** In development, a console warning when Lede's tokens aren't on the page, where the screen would draw unstyled. */
function useTokensCheck(root: React.RefObject<HTMLElement | null>) {
  React.useEffect(() => {
    if (!development || warned || !root.current) return;
    if (getComputedStyle(root.current).getPropertyValue('--radius-step').trim()) return;
    warned = true;
    console.warn('SpecView: Lede’s tokens aren’t on the page, so the screen draws unstyled. Import Lede’s CSS in your app’s CSS, such as @import "./styles/lede/index.css".');
  }, [root]);
}

import { validateSpec, type ActionBinding, type Spec, type UIElement } from '@json-render/core';
import { z } from 'zod';
import { catalog, functions } from './catalog';

type Entry = { props: z.ZodObject; events?: readonly string[]; slots?: readonly string[] };
const components = catalog.data.components as Record<string, Entry>;
const statePath = z.string().startsWith('/');
/** The params of each action a spec can bind: json-render's built-ins, then the catalog's own. */
const actions: Record<string, z.ZodObject> = {
  setState: z.object({ statePath, value: z.unknown() }),
  pushState: z.object({ statePath, value: z.unknown(), clearStatePath: statePath.optional() }),
  removeState: z.object({ statePath, index: z.number().int().min(0) }),
  validateForm: z.object({ statePath: statePath.optional() }),
  ...Object.fromEntries(Object.entries(catalog.data.actions).map(([name, a]) => [name, a.params as z.ZodObject])),
};

/** A value json-render resolves at render time, such as `{ "$bindState": "/form/name" }`. */
const isExpression = (value: unknown) =>
  !!value && typeof value === 'object' && !Array.isArray(value) && Object.keys(value).some((key) => key.startsWith('$'));
const list = (bound: ActionBinding | ActionBinding[] | undefined) => (Array.isArray(bound) ? bound : bound ? [bound] : []);

/** Every `$state` path a condition reads, such as `/open` in `[{ "$state": "/open" }, { "$item": "id", "eq": { "$state": "/open" } }]`. */
const reads = (condition: unknown): string[] =>
  !condition || typeof condition !== 'object' ? []
  : Object.entries(condition).flatMap(([key, value]) => (key === '$state' && typeof value === 'string' ? [value] : reads(value)));
/** Each function a value calls with `$computed`, at any depth. */
const computed = (value: unknown): string[] =>
  !value || typeof value !== 'object' ? []
  : [...(typeof (value as { $computed?: unknown }).$computed === 'string' ? [(value as { $computed: string }).$computed] : []), ...Object.values(value).flatMap(computed)];
/** The tests a `visible` joins, each a test of one value. */
const tests = (visible: unknown): Array<Record<string, unknown>> => {
  if (Array.isArray(visible)) return visible.flatMap(tests);
  if (!visible || typeof visible !== 'object') return [];
  const v = visible as Record<string, unknown>;
  return v.$and || v.$or ? tests(v.$and ?? v.$or) : [v];
};

/**
 * Whether setting `path` to `value` shows a View of `spec`: one whose `visible` reads the path and passes for it. A
 * literal `eq` passes for its own value, `not` for an empty one, and a test against another value, such as an item's
 * id in a repeated detail, for any value that isn't empty. A value json-render fills in, such as `{ "$template": "${id}" }`,
 * counts as one that isn't empty.
 */
export function showsView(spec: Spec, path: unknown, value: unknown): boolean {
  const filled = isExpression(value) || !!value;
  return Object.values(spec.elements ?? {}).some((el) => el.type === 'View' && tests(el.visible).some((t) => {
    if (t.$state !== path) return reads(t).includes(String(path)) && filled;
    if ('eq' in t && !isExpression(t.eq)) return isExpression(value) || t.eq === value;
    return t.not === true ? !filled : filled;
  }));
}

/** Whether a binding opens a View of `spec` in place: one of its actions sets the path that View's `visible` reads. */
export const opensView = (spec: Spec, bound: ActionBinding | ActionBinding[] | undefined) =>
  list(bound).some((b) => b.action === 'setState' && showsView(spec, b.params?.statePath, b.params?.value));

/**
 * Presses that promise more than the spec holds. A ListRow's press draws a chevron, which says the row opens
 * something, so its press sets a path that a View's `visible` reads. A detail's PageHeader with `back` binds “back”.
 */
export function promises(spec: Spec): string[] {
  return Object.entries(spec.elements ?? {}).flatMap(([key, el]) => {
    if (el.type === 'ListRow' && el.on?.press && !opensView(spec, el.on.press))
      return [`elements.${key}.on.press: a row's press shows a chevron, so it opens a View: set the path a View's visible reads, or leave press out`];
    if (el.type === 'PageHeader' && el.props?.back && !el.on?.back)
      return [`elements.${key}.on.back: a PageHeader with back binds “back” to the setState that shows the list View again`];
    return [];
  });
}

/**
 * Each issue with values against a schema. A key the schema doesn't have is one, whatever its value. A value bound to
 * an expression, which json-render resolves later, may be left out.
 */
function parse(where: string, schema: z.ZodObject, values: Record<string, unknown>): string[] {
  const known = Object.entries(values).filter(([name]) => name in schema.shape);
  const unknown = Object.keys(values).filter((name) => !(name in schema.shape)).map((name) => `${where}: Unrecognized key: "${name}"`);
  const bound = Object.fromEntries(known.filter(([, value]) => isExpression(value)).map(([name]) => [name, true] as const));
  const parsed = schema.partial(bound as Record<string, true> & Record<number, never>).safeParse(Object.fromEntries(known.filter(([name]) => !(name in bound))));
  return [...unknown, ...(parsed.success ? [] : parsed.error.issues.map((i) => `${where}${i.path.map((p) => `.${String(p)}`).join('')}: ${i.message}`))];
}

/** An action that doesn't exist, or params its schema rejects. */
function action(where: string, b: ActionBinding): string[] {
  const schema = actions[b.action];
  if (!schema) return [`${where}.action: there is no action “${b.action}”. The actions are ${Object.keys(actions).join(', ')}.`];
  return parse(`${where}.params`, schema, b.params ?? {});
}

/** Each issue with an element's `on` and `watch`: an event its type doesn't emit, and each binding's action. */
function bindings(key: string, element: UIElement, entry: Entry): string[] {
  const at = (where: string, bound: ActionBinding | ActionBinding[]) =>
    list(bound).flatMap((b, i) => action(Array.isArray(bound) ? `${where}.${i}` : where, b));
  const on = Object.entries(element.on ?? {}).flatMap(([event, bound]) => [
    ...(entry.events?.includes(event) ? [] : [`elements.${key}.on.${event}: ${element.type} has no event “${event}”.${entry.events?.length ? ` Its events are ${entry.events.join(', ')}.` : ''}`]),
    ...at(`elements.${key}.on.${event}`, bound),
  ]);
  const watch = Object.entries(element.watch ?? {}).flatMap(([path, bound]) => at(`elements.${key}.watch.${path}`, bound));
  return [...on, ...watch];
}

/**
 * Every issue with a spec, as a line of text. json-render's `catalog.validate` checks the spec's shape and that each
 * type is in the catalog, and `validateSpec` checks its structure. Neither reads an element's props or bindings, so
 * the next passes parse each element's props with its entry's schema, check each `on` and `watch` binding's event,
 * action and params, and each slot and `$computed` function it names. The last checks what a press promises.
 */
export function check(spec: Spec): string[] {
  const shape = catalog.validate(spec);
  const issues = shape.success ? [] : shape.error!.issues.map((i) => `${i.path.join('.')}: ${i.message}`);
  issues.push(...validateSpec(spec).issues.map((i) => `${i.elementKey ?? 'spec'}: ${i.message}`));
  for (const [key, element] of Object.entries(spec.elements ?? {})) {
    const entry = components[element.type];
    if (!entry) continue;
    issues.push(...parse(`elements.${key}.props`, entry.props, element.props ?? {}));
    issues.push(...bindings(key, element, entry));
    for (const slot of Object.keys(element.slots ?? {}).filter((s) => s === 'default' || !entry.slots?.includes(s)))
      issues.push(`elements.${key}.slots.${slot}: ${element.type} has no slot “${slot}”.${slot === 'default' ? ' Its children fill the default slot.' : ''}`);
    for (const name of computed([element.props, element.visible, element.on, element.watch]).filter((n) => !(n in functions)))
      issues.push(`elements.${key}: there is no function “${name}” for $computed. The functions are ${Object.keys(functions).join(', ')}.`);
  }
  issues.push(...promises(spec));
  return issues;
}

import { SPEC_DATA_PART_TYPE, type Spec } from '@json-render/core';
import { buildSpecFromParts } from '@json-render/react';

const pointer = (key: string) => key.replaceAll('~', '~0').replaceAll('/', '~1');

/**
 * A spec as the JSONL patches a model streams: the root, each element after its parent, so the screen fills in from
 * the top, and then the state, each array an item at a time, as json-render's prompt asks. A list drawn with repeat
 * fills in a row at a time. A mock transport replays these, and a server can send them back to the model, so it sees
 * the screens it sent in earlier turns.
 */
export function toPatches(spec: Spec): string[] {
  const lines: Array<{ op: 'add'; path: string; value: unknown }> = [{ op: 'add', path: '/root', value: spec.root }];
  const queue = [spec.root];
  for (const seen = new Set<string>(); queue.length; ) {
    const key = queue.shift()!;
    const element = spec.elements[key];
    if (!element || seen.has(key)) continue;
    seen.add(key);
    lines.push({ op: 'add', path: `/elements/${pointer(key)}`, value: element });
    queue.push(...(element.children ?? []), ...Object.values(element.slots ?? {}).flat());
  }
  if (spec.state) {
    lines.push({ op: 'add', path: '/state', value: {} });
    for (const [key, value] of Object.entries(spec.state)) {
      const path = `/state/${pointer(key)}`;
      if (!Array.isArray(value)) lines.push({ op: 'add', path, value });
      else lines.push({ op: 'add', path, value: [] }, ...value.map((item, i) => ({ op: 'add' as const, path: `${path}/${i}`, value: item })));
    }
  }
  return lines.map((line) => `${JSON.stringify(line)}\n`);
}

/**
 * The spec a message's parts build, without changing them. json-render's `buildSpecFromParts` applies each patch's
 * value as it is, so a later patch such as `/state/items/0` writes into an array an earlier patch carried, and a second
 * build adds the items again: a list re-rendered while it streams grows on every render. This builds from copies.
 */
export function specFromParts(parts: ReadonlyArray<{ type: string; data?: unknown }>): Spec | null {
  return buildSpecFromParts(parts.filter((part) => part.type === SPEC_DATA_PART_TYPE).map((part) => ({ type: part.type, data: structuredClone(part.data) })));
}

